steps.codeExample:
-- Cria um índice B-Tree para acelerar buscas por email
CREATE INDEX idx_usuarios_email ON usuarios(email);

-- Verifica se o PostgreSQL está usando Index Scan ou Seq Scan
EXPLAIN ANALYZE
SELECT id, nome FROM usuarios WHERE email = 'ana@dev.com';

-- Salva uma consulta como View reutilizável
CREATE VIEW vw_resumo_vendas AS
SELECT categoria, COUNT(*) AS qtd FROM vendas GROUP BY categoria;
